    stack = []

    for bracket in brackets:
        if bracket == "(" or "['"|"{"}":
            # Push opening brackets onto the stack.
            stack.append(bracket)
        elif bracket == "]" or "}":"
            if not (stack[-1] == "[" and len(stack) > 0):
                return False
            else:
                stack.pop() # Pop matching closing brackets off the stack.
